cas:[["17. století","Doba Ludvíka XIV.; lékařství založené na pouštění žilou, klystýrech a latinských frázích."],["Jeden den","Od Arganova počítání účtů za léky ráno po fingovanou smrt a „promoci“ večer."]],
prostor:[["Paříž – **Arganův pokoj**","Celý děj v Arganově domě (jednota místa); Argan nevychází, „je přece nemocný“."]],
temata:[["**Hypochondrie** a sobectví","Argan je zdravý, ale přesvědčený o své nemoci; dceru chce provdat za lékaře jen kvůli sobě – aby měl lékaře zadarmo v rodině."],["**Kritika lékařů**","Doktoři Purgon a Diafoirus i lékárník Fleurant ždímají Argana penězi, mluví latinou a nic neumí; bratr Béralde jim nevěří."],["Pokrytectví a chamtivost","Druhá žena **Belina** předstírá lásku, ve skutečnosti čeká na dědictví (s notářem chystá závěť)."],["Láska vs. vůle otce","Angelika miluje Kleanta, otec ji nutí do sňatku s hloupým Tomášem Diafoirusem nebo do kláštera."]],
dej:"Bohatý měšťan **Argan** si namlouvá, že je vážně nemocný, a utrácí za léky a lékaře. Aby měl lékaře stále po ruce, chce provdat dceru **Angeliku** za mladého lékaře **Tomáše Diafoiruse**, ačkoli ona miluje **Kleanta**. Druhá Arganova žena **Belina** předstírá péči, ale chce, aby dceru poslal do kláštera a majetek odkázal jí. Chytrá služka **Toinetta** stojí na straně Angeliky: Kleant se do domu dostane jako učitel zpěvu a při „lekci“ si s Angelikou vyzná lásku ve zpěvu. Arganův bratr **Béralde** mu vyčítá důvěru v lékaře. Toinetta se převlékne za lékaře a absurdními radami zesměšní medicínu. Nakonec navrhne, aby Argan předstíral smrt: Belina se raduje a hned shání klíče, kdežto Angelika upřímně truchlí. Argan „vstane z mrtvých“, prohlédne Belinu a svolí ke sňatku s Kleantem – pokud se stane lékařem. Béralde navrhne, ať se lékařem stane rovnou Argan; hra končí burleskní **promocí** v kuchyňské latině.",
postavy:[["Argan","hlavní postava, „zdravý nemocný“","**hypochondr** – počítá klystýry a pilulky, bojí se pohnout","**sobecký** – dceru chce dát za lékaře kvůli sobě","**důvěřivý** – věří lékařům i Belině, nevidí její přetvářku"],["Toinetta","služka","**chytrá a prostořeká** – odmlouvá pánovi, směje se lékařům","vynalézavá – převlek za lékaře, nápad s fingovanou smrtí","věrná Angelice"],["Belina","Arganova druhá žena","**pokrytecká** – předstírá lásku","chamtivá – čeká na dědictví, raduje se z jeho „smrti“","intrikánka – chce Angeliku poslat do kláštera"],["Angelika","Arganova dcera","zamilovaná do Kleanta","poslušná, ale odmítne sňatek s Tomášem","upřímná – nad „mrtvým“ otcem pláče"],["Béralde / Diafoirusové / Purgon","Arganův bratr / otec a syn lékaři / Arganův lékař","Béralde – rozumný, hlas autora","Tomáš Diafoirus – hloupý, naučené fráze","Purgon – domýšlivý, vyhrožuje Arganovi nemocemi"]],
vyp:{drama:true},
ukazky:[["**Úvodní monolog** – Argan počítá účty lékárníka","Argan sčítá klystýry a pilulky a smlouvá o ceně – hned charakterizuje jeho hypochondrii i lakotu."],["**Fingovaná smrt** (3. dějství)","Belina se nad „mrtvým“ raduje, Angelika pláče – zkouška upřímnosti, která vede k rozuzlení."],["Toinetta převlečená za lékaře","Za všechno může „plíce“; radí uříznout ruku a vypíchnout oko – zesměšnění medicíny."]],
jazyk:{a:"spisovný jazyk, živé dialogy; satira, komika situační (převleky, fingovaná smrt) a slovní (latina lékařů, opakované „plíce!“); mluvící jména (Purgon – purgatio = očista, projímadlo)",b:"krátké repliky, otázky a zvolání; dlouhé řečnické promluvy lékařů parodují učenost",c:"dramatický text – dialog, monology, scénické poznámky; odborná lékařská a latinská slova jako prostředek komiky"},
zpusoby:["drama – bez vypravěče","jednání postav z dialogů a scénických poznámek"],
promluvy:["dialog, monolog, zpěv (milostná „lekce“), řeč stranou","Toinetta: „Plíce!“ – opakovaná odpověď na všechny Arganovy potíže"],vers:null,
autor:{zivot:["viz Lakomec: **Jean-Baptiste Poquelin** (1622–1673)","syn královského čalouníka, právník, herec a ředitel divadla","přízeň Ludvíka XIV.","sám nemocný (tuberkulóza) – hru psal s nadhledem i hořkostí","při 4. představení (17. 2. 1673) mu na jevišti jako Arganovi bylo zle, téhož večera zemřel"],znaky:["komedie charakterů – zesměšnění jedné lidské vady","satira na lékaře, měšťany, pokrytce","lidová fraška + klasicistní pravidla","komedie-balet – spojení hry, hudby a tance"]},
